export const GET = handle;
export const POST = handle;
import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { getOwnProfile } from "@/lib/auth";
import { AuthButton } from "@/components/auth-button";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

export default async function Profile() {
  const result = await getOwnProfile(await headers());
  if (result.status === "signed-out") redirect("/");
  return (
    <main className="mx-auto w-full max-w-2xl p-6 sm:py-16">
      {result.status === "available" ? (
        <Card>
          <CardHeader>
            <CardTitle className="text-3xl font-semibold tracking-tight">
              <h1>Your Workspace profile</h1>
            </CardTitle>
            <CardDescription>Current shared information from Google Workspace.</CardDescription>
            <CardAction>
              <Badge variant="secondary">Current from Google Workspace</Badge>
            </CardAction>
          </CardHeader>
          <CardContent>
            <dl className="flex flex-col gap-5">
              <div className="flex flex-col gap-1">
                <dt className="font-medium">Name</dt>
                <dd>{result.profile.name?.fullName ?? "Unavailable"}</dd>
              </div>
              <div className="flex flex-col gap-1">
                <dt className="font-medium">Workspace email</dt>
                <dd className="break-all">{result.profile.primaryEmail}</dd>
              </div>
              <div className="flex flex-col gap-1">
                <dt className="font-medium">Contact emails</dt>
                <dd>
                  {result.profile.emails === undefined ? (
                    "Unavailable"
                  ) : result.profile.emails.length === 0 ? (
                    "No shared entries"
                  ) : (
                    <ul>
                      {result.profile.emails.map((entry, index) => (
                        <li key={index} className="break-all">
                          {entry.address}
                        </li>
                      ))}
                    </ul>
                  )}
                </dd>
              </div>
              <div className="flex flex-col gap-1">
                <dt className="font-medium">Phones</dt>
                <dd>
                  {result.profile.phones === undefined ? (
                    "Unavailable"
                  ) : result.profile.phones.length === 0 ? (
                    "No shared entries"
                  ) : (
                    <ul>
                      {result.profile.phones.map((entry, index) => (
                        <li key={index}>{entry.value}</li>
                      ))}
                    </ul>
                  )}
                </dd>
              </div>
            </dl>
          </CardContent>
          <CardFooter>
            <AuthButton action="sign-out" />
          </CardFooter>
        </Card>
      ) : (
        <Card role="alert">
          <CardHeader>
            <CardTitle className="text-3xl font-semibold tracking-tight">
              <h1>
                {result.status === "reconnect"
                  ? "Reconnect your Google account"
                  : "Workspace profile unavailable"}
              </h1>
            </CardTitle>
            <CardDescription>
              {result.status === "reconnect"
                ? "Your Google connection needs to be renewed."
                : "Google Workspace could not provide your current profile."}
            </CardDescription>
          </CardHeader>
          <CardContent>
            <p className="text-muted-foreground">
              {result.status === "reconnect"
                ? "Google rejected your connection or could not confirm your identity. Reconnect with your managed account."
                : "Your current profile could not be retrieved. It may be hidden or unavailable, or Google may be temporarily unreachable."}
            </p>
          </CardContent>
          <CardFooter className="gap-2">
            {result.status === "reconnect" ? (
              <AuthButton action="reconnect" />
            ) : (
              <form action="/profile" method="get">
                <Button type="submit">Try again</Button>
              </form>
            )}
            <AuthButton action="sign-out" />
          </CardFooter>
        </Card>
      )}
    </main>
  );
}

